// File: notification-client/src/components/DeliveryDetails.jsx
import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';

const DeliveryDetails = () => {
  const { id } = useParams(); // Get Delivery ID from URL
  const [delivery, setDelivery] = useState(null);

  useEffect(() => {
    // Fetch delivery details from backend
    const fetchDelivery = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/deliveries/${id}`);
        setDelivery(response.data); // Assuming API returns {customerId, driverId, status, deliveryAddress}
      } catch (error) {
        console.error('Failed to fetch delivery details:', error);
      }
    };

    fetchDelivery();
  }, [id]);

  if (!delivery) {
    return <p>Loading delivery details...</p>;
  }

  const googleMapsLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(delivery.deliveryAddress)}`;

  return (
    <div style={{ padding: '2rem', fontFamily: 'Arial' }}>
      <h1>📦 Delivery Details</h1>

      <p><strong>Customer ID:</strong> {delivery.customerId}</p>
      <p><strong>Status:</strong> {delivery.status}</p>
      <p><strong>Driver ID:</strong> {delivery.driverId}</p>
      <p><strong>Delivery Address:</strong> {delivery.deliveryAddress}</p>

      <div style={{ marginTop: '2rem', display: 'flex', gap: '1rem' }}>
        <button
          style={{
            backgroundColor: 'gray',
            color: 'white',
            padding: '10px 20px',
            border: 'none',
            borderRadius: '5px',
            cursor: 'pointer'
          }}
          onClick={() => window.history.back()}
        >
          ← Back to Dashboard
        </button>

        <a
          href={googleMapsLink}
          target="_blank"
          rel="noopener noreferrer"
        >
          <button
            style={{
              backgroundColor: 'blue',
              color: 'white',
              padding: '10px 20px',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer'
            }}
          >
            📍 Track on Map
          </button>
        </a>
      </div>
    </div>
  );
};

export default DeliveryDetails;
